import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Home = ({ accessToken }) => {
  const [orgInfo, setOrgInfo] = useState(null);

  useEffect(() => {
    const fetchOrgInfo = async () => {
      try {
        const response = await axios.get('https://devsafa-dev-ed.develop.my.salesforce.com/services/data/v52.0/', {
          headers: {
            Authorization: `Bearer ${accessToken}`,
          },
        });
        setOrgInfo(response.data);
      } catch (error) {
        console.error('Error fetching org information:', error);
      }
    };

    if (accessToken) {
      fetchOrgInfo();
    }
  }, [accessToken]);

  if (!orgInfo) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h1>Salesforce Org Information</h1>
      <pre>{JSON.stringify(orgInfo, null, 2)}</pre>
    </div>
  );
};

export default Home;
